function validate([word, k]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 100000) return 'word needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(word)) return 'word may contain only lowercase letters.';
  if (!Number.isInteger(k) || k < 0 || k > 100000) return 'k is an integer between 0 and 100000.';
  return null;
}

