function minimumDeletions(word, k) {
  const counts = new Array(26).fill(0);
  for (const ch of word) {
    counts[ch.charCodeAt(0) - 97]++;
  }
  const freqs = counts.filter((count) => count > 0);
  let best = word.length;

  for (const low of freqs) {
    let deleted = 0;
    for (const freq of freqs) {
      if (freq < low) {
        deleted += freq;
      } else if (freq > low + k) {
        deleted += freq - low - k;
      }
    }
    best = Math.min(best, deleted);
  }
  return best;
}

