function minimumDeletions(word, k) {
  // Try every possible smallest surviving count, from 1 up to the largest count, and keep as much as allowed.
  const counts = {};
  for (const ch of word) counts[ch] = (counts[ch] || 0) + 1;
  const values = Object.values(counts);
  const top = Math.max(...values);
  let mostKept = 0;
  for (let floor = 1; floor <= top; floor++) {
    let kept = 0;
    for (const c of values) if (c >= floor) kept += Math.min(c, floor + k);
    mostKept = Math.max(mostKept, kept);
  }
  return word.length - mostKept;
}

