function generate(rand, size) {
  if (size === 'large') {
    const n = 10000;
    const weights = Array.from({ length: 26 }, () => Math.pow(rand(), 3));
    const total = weights.reduce((a, b) => a + b, 0);
    let word = '';
    for (let i = 0; i < n; i++) {
      let pick = rand() * total;
      let letter = 0;
      while (letter < 25 && pick >= weights[letter]) { pick -= weights[letter]; letter++; }
      word += String.fromCharCode(97 + letter);
    }
    const k = rand() < 0.2 ? 0 : Math.floor(rand() * 400);
    return [word, k];
  }
  const n = 1 + Math.floor(rand() * 9);
  const alphabet = 1 + Math.floor(rand() * 4);
  let word = '';
  for (let i = 0; i < n; i++) word += String.fromCharCode(97 + Math.floor(rand() * alphabet));
  const k = Math.floor(rand() * 5);
  return [word, k];
}
